  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message)); await page.exposeFunction('__toast', (t) => { lastToast = t; }); await page.addInitScript(() => { document.addEventListener('DOMContentLoaded', () => { const t = document.getElementById('toast'); if (t) new MutationObserver(() => { if (t.textContent) window.__toast(t.textContent); }).observe(t, { childList: true, characterData: true, subtree: true }); }); }); page.on('crash', () => errors.push('PAGE CRASHED')); page.on('console', (m) => { if (m.type() === 'error' && !/Failed to load resource/.test(m.text())) errors.push('console: ' + m.text()); }); // blocked CDN and the 4xx answers of the negative checks are expected
