    const r = await ev((dest) => { const x = HB.views.planning.requestRows(HB.app.store).filter((q) => q.client === 'Jamara' && q.destination === dest).pop(); return x && { id: x.id, status: x.liveStatus, ok: x.routeCheck.ok, approved: x.routeApproved }; }, dest);
