    const planBlocked = await ev(async (id) => { const s = HB.app.store; const cur = s.state.requests.find((x) => x.id === id); try { await s.saveDoc('requests', { id, plan: { approvedQty: 1, approvedBy: 'ops', approvedAt: new Date().toISOString() }, status: 'Plan Approved' }, { expectedVersion: cur.version }); return 'accepted'; } catch (e) { return e.code || e.message; } }, unmappedId); if (planBlocked === 'accepted') throw new Error('plan approved on an unmapped route');
