    const sub = await ev(async (id) => { const s = HB.app.store; const cur = s.state.requests.find((x) => x.id === id); await s.saveDoc('requests', { id, submittedAt: new Date().toISOString(), submittedBy: s.user.username, status: 'Awaiting Planning' }, { expectedVersion: cur.version }); return HB.views.planning.requestRows(s).find((x) => x.id === id).liveStatus; }, unmappedId); if (sub !== 'Awaiting Planning') throw new Error('status after mapping ' + sub);
